`timescale 1ns/1ps
// -----------------------------------------------------------------------------
// rv_imem - instruction ROM, 256 x 32 bit, asynchronous read
//
// Contents come from program.hex (one 32-bit hex word per line, 256 lines,
// generated by tools/gen_program.py). addr is the word address pc[9:2].
// -----------------------------------------------------------------------------
module rv_imem (
    input  wire [7:0]  addr,
    output wire [31:0] instr
);

  reg [31:0] mem [0:255];

  initial $readmemh("program.hex", mem);

  assign instr = mem[addr];

endmodule
